insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_jiranga_monastery','Jiranga Tibetan Monastery (Chandragiri) & Khasada','Odisha','Gajapati','Heritage','Jiranga (Padmasambhava Mahavihara) in Chandragiri is South India''s largest Tibetan Buddhist monastery. Inaugurated by His Holiness Dalai Lama in 2010, the 70-foot high monastery complex features traditional Tibetan stupas, vibrant frescoes, a 23-foot Buddha statue, prayer wheels, and Tibetan carpet weaving centers.','19.3167','84.2667','needs_review','October – March','1',array['buddhism','tibetan monastery','dalai lama','waterfall','culture','peaceful','hidden gem']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
