insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_khandadhar_sng','Khandadhar Waterfall (Sundargarh)','Odisha','Sundargarh','Waterfall','Khandadhar in Sundargarh is a breathtaking 244-meter (801 ft) perennial cascade resembling a sharp sword edge (''Khanda Dhara''). Encircling dense virgin forests of the Chelligarh mountain range, it is one of eastern India''s most dramatic natural spectacles.','21.9056','85.0083','needs_review','October – March','1',array['waterfall','highest waterfall','trekking','forest','sal woods','adventure']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_mandira_dam','Mandira Dam & Reservoir','Odisha','Sundargarh','Lake','Built across the Sankha river, Mandira Dam creates a sweeping lake surrounded by picturesque emerald hills. It serves as water supply to Rourkela Steel Plant and doubles as a premier leisure and boating retreat.','22.2858','84.6681','needs_review','October – March','1',array['dam','lake','boating','hills','sunset','peaceful']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_vedvyas','Vedvyas Temple & Confluence','Odisha','Sundargarh','Heritage','Located on the western outskirts of Rourkela, Vedvyas is deeply revered in Hindu mythology as the hermitage of Maharishi Ved Vyasa where he is believed to have composed the epic Mahabharata. The confluence of rivers Sankha and Koel gives birth to the mighty Brahmani river here.','22.2478','84.7892','needs_review','October – March','1',array['temple','confluence','mahabharata','heritage','spiritual','rivers']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
