insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_akhandalamani','Baba Akhandalamani Temple (Aradi)','Odisha','Bhadrak','Temple','Situated on the banks of river Baitarani, the Baba Akhandalamani Temple is revered throughout Eastern India. Devotees from Odisha, Bengal, and Jharkhand visit to seek blessings for relief from ailments. The present temple structure was patronized by King Niladri Dingh in the 17th century.','20.8841','86.6894','needs_review','October – March','1',array['shiva','temple','river baitarani','spiritual','healing','pilgrimage']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_dhamra_port','Dhamra Port, Beach & Estuary','Odisha','Bhadrak','Beach','Located where the Dhamra river merges with the Bay of Bengal, Dhamra offers a captivating blend of cutting-edge deep-water port engineering, serene coastal backwaters, and pristine estuarine ecology adjoining Gahirmatha marine sanctuary.','20.8252','86.9733','needs_review','November – March','1',array['coastal','port','estuary','olive ridley','mangroves','engineering']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sarala_temple','Maa Sarala Peetha (Jhankad)','Odisha','Jagatsinghpur','Heritage','Maa Sarala Temple at Jhankad is one of the eight most sacred Shakta shrines of Odisha. Here in the 15th century, the unlettered ploughman Siddheswar Parida received the goddess''s divine grace to become Adi Kavi Sarala Das and compose the monumental 18-volume Odia Mahabharata, Chandi Purana, and Bilanka Ramayana.','20.315','86.3022','needs_review','October – March','1',array['shakti','temple','epic literature','sarala das','heritage','spiritual']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_paradip_beach','Paradip Sea Beach & Light House','Odisha','Jagatsinghpur','Beach','Paradip offers a dynamic maritime atmosphere where the massive Mahanadi river joins the Bay of Bengal. Highlights include the iconic 40-meter Paradip Light House with panoramic coastal vistas, a vibrant beach lined with sea pines, a marine aquarium, and the thrilling sight of international cargo ships on the horizon.','20.2644','86.6715','needs_review','October – March','1',array['beach','light house','port','mahanadi confluence','marine aquarium','sunset']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
