insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sureswari','Sureswari Temple & Mahanadi Confluence','Odisha','Subarnapur','Heritage','Sonepur, known as the ''Second Varanasi of India'', is crowned by the Maa Sureswari Temple built by King Subarnakeshari in the 10th century. Overlooking the grand sangam (confluence) where the river Tel merges into the Mahanadi, the shrine is a celebrated center of Tantric and Shakta veneration.','20.84','83.92','needs_review','October – March','1',array['shakti','temple','mahanadi','tel river','confluence','tantra','sonepur']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_subarnameru','Subarnameru Temple & Silk Weavers Village','Odisha','Subarnapur','Heritage','Subarnameru Temple on the banks of river Tel is dedicated to Lord Shiva. Local lore recounts that gold coins once showered upon this shrine, giving the town its name ''Subarnapur'' (City of Gold). Adjacent weaving clusters produce the GI-tagged Sonepuri and Bomkai silk sarees with intricate double-ikat motifs.','20.835','83.915','needs_review','October – March','1',array['temple','shiva','silk','handloom','bomkai','craft','heritage']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_koili_ghoghar','Koili Ghoghar Waterfall & Cave Temple','Odisha','Jharsuguda','Waterfall','Koili Ghoghar is nestled in the dense reserve forests of Lakhanpur in Jharsuguda district. The rivulets of the ''Ahiraj'' nallah cascade down stepped rock tiers from a height of 200 feet into a tranquil natural gorge. Inside a rock cave beneath the stream sits a submerged, perennially wet Shiva Lingam known as Maheshwarnath.','21.6833','83.5667','needs_review','October – March','1',array['waterfall','cave temple','submerged lingam','sal forest','stream','nature']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_bikramkhol','Bikramkhol Prehistoric Rock Art & Cave','Odisha','Jharsuguda','Heritage','Hidden in the reserve forests of Belpahar, Bikramkhol is one of the world''s most debated epigraphic discoveries. Discovered in the 1930s by K.P. Jayaswal, the 37-meter sandstone rock shelter contains geometric and pictographic characters carved and painted into the rock face, dated between 3000 BC and 1500 BC.','21.7833','83.6167','needs_review','October – March','1',array['rock art','prehistoric','pictographic','bronze age','caves','ancient script']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
